content:
1|html,
2|body,
3|#app {
4|  margin: 0;
5|  padding: 0;
6|  height: 100%;
7|  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue',
8|    Arial, 'Noto Sans', sans-serif;
9|  background: linear-gradient(135deg, #eaf3ff 0%, #f5f9ff 40%, #eef6ff 100%);
10|  background-attachment: fixed;
11|  color: #1f2937;
12|}
13|
14|* {
15|  box-sizing: border-box;
16|}
17|
18|/* ===== 全局浅色科技蓝主题变量 ===== */
19|:root {
20|  --bg-page: #eaf3ff;
21|  --bg-card: #ffffff;
22|  --bg-card-hover: #f0f7ff;
23|  --bg-input: #ffffff;
24|  --border-color: #dbe7f5;
25|  --border-color-light: #c9ddf5;
26|  --text-primary: #1f2937;
27|  --text-secondary: #4b5563;
28|  --text-muted: #8a94a6;
29|  --accent: #3b82f6;
30|  --accent-hover: #2563eb;
31|}
32|
33|/* ===== ElementUI 组件黑色主题覆盖 ===== */
34|
35|/* 卡片 */
36|.el-card {
37|  border-radius: 4px;
38|  background-color: var(--bg-card);
39|  border-color: var(--border-color);
40|  color: var(--text-primary);
41|}
42|.el-card__header {
43|  border-bottom: 1px solid var(--border-color);
44|  color: var(--text-primary);
45|}
46|
47|/* 输入框 */
48|.el-input__inner,
49|.el-textarea__inner {
50|  background-color: var(--bg-input);
51|  border-color: var(--border-color);
52|  color: var(--text-primary);
53|}
54|.el-input__inner::placeholder,
55|.el-textarea__inner::placeholder {
56|  color: var(--text-muted);
57|}
58|.el-input__inner:focus,
59|.el-textarea__inner:focus {
60|  border-color: var(--accent);
61|}
62|.el-input-group__append {
63|  background-color: var(--bg-input);
64|  border-color: var(--border-color);
65|  color: var(--text-secondary);
66|}
67|.el-input__prefix,
68|.el-input__suffix {
69|  color: var(--text-muted);
70|}
71|
72|/* 下拉选择 */
73|.el-select-dropdown {
74|  background-color: var(--bg-card);
75|  border-color: var(--border-color);
76|}
77|.el-select-dropdown__item {
78|  color: var(--text-primary);
79|}
80|.el-select-dropdown__item.hover,
81|.el-select-dropdown__item:hover {
82|  background-color: var(--bg-card-hover);
83|}
84|.el-select-dropdown__item.selected {
85|  color: var(--accent);
86|}
87|.el-select .el-input__inner {
88|  background-color: var(--bg-input);
89|  color: var(--text-primary);
90|}
91|.el-select__tags .el-tag {
92|  background-color: var(--bg-card-hover);
93|  border-color: var(--border-color);
94|  color: var(--text-primary);
95|}
96|
97|/* 弹窗 */
98|.el-dialog {
99|  background-color: var(--bg-card);
100|  border-radius: 12px;
101|}
102|.el-dialog__title {
103|  color: var(--text-primary);
104|}
105|.el-dialog__header {
106|  border-bottom: 1px solid var(--border-color);
107|}
108|.el-dialog__body {
109|  color: var(--text-primary);
110|}
111|.el-dialog__footer {
112|  border-top: 1px solid var(--border-color);
113|}
114|
115|/* 表单 */
116|.el-form-item__label {
117|  color: var(--text-secondary);
118|}
119|
120|/* 表格 */
121|.el-table {
122|  background-color: var(--bg-card);
123|  color: var(--text-primary);
124|}
125|.el-table th.el-table__cell {
126|  background-color: var(--bg-card-hover);
127|  color: var(--text-primary);
128|  border-bottom: 1px solid var(--border-color);
129|}
130|.el-table td.el-table__cell {
131|  border-bottom: 1px solid var(--border-color);
132|}
133|.el-table tr {
134|  background-color: var(--bg-card);
135|}
136|.el-table--enable-row-hover .el-table__body tr:hover > td.el-table__cell {
137|  background-color: var(--bg-card-hover);
138|}
139|.el-table__empty-block {
140|  background-color: var(--bg-card);
141|}
142|.el-table__empty-text {
143|  color: var(--text-muted);
144|}
145|
146|/* 分页 */
147|.el-pagination {
148|  color: var(--text-secondary);
149|}
150|.el-pagination.is-background .el-pager li {
151|  background-color: var(--bg-card-hover);
152|  color: var(--text-secondary);
153|}
154|.el-pagination.is-background .el-pager li:not(.disabled):hover {
155|  color: var(--accent);
156|}
157|.el-pagination.is-background .el-pager li.active {
158|  background-color: var(--accent);
159|  color: #fff;
160|}
161|.el-pagination.is-background .btn-prev,
162|.el-pagination.is-background .btn-next {
163|  background-color: var(--bg-card-hover);
164|  color: var(--text-secondary);
165|}
166|
167|/* 标签 */
168|.el-tag {
169|  background-color: var(--bg-card-hover);
170|  border-color: var(--border-color);
171|  color: var(--text-secondary);
172|}
173|
174|/* 空状态 */
175|.el-empty__description p {
176|  color: var(--text-muted);
177|}
178|
179|/* 消息提示 */
180|.el-message {
181|  background-color: var(--bg-card);
182|  border-color: var(--border-color);
183|  color: var(--text-primary);
184|}
185|
186|/* 确认框 */
187|.el-message-box {
188|  background-color: var(--bg-card);
189|  border-color: var(--border-color);
190|}
191|.el-message-box__title {
192|  color: var(--text-primary);
193|}
194|.el-message-box__content {
195|  color: var(--text-secondary);
196|}
197|
198|/* 加载遮罩 */
199|.el-loading-mask {
200|  background-color: rgba(15, 17, 21, 0.7);
201|}
202|
203|/* 下拉菜单 */
204|.el-dropdown-menu {
205|  background-color: var(--bg-card);
206|  border-color: var(--border-color);
207|}
208|.el-dropdown-menu__item {
209|  color: var(--text-primary);
210|}
211|.el-dropdown-menu__item:not(.is-disabled):hover {
212|  background-color: var(--bg-card-hover);
213|  color: var(--accent);
214|}
215|
216|/* 开关 */
217|.el-switch__label {
218|  color: var(--text-secondary);
219|}
220|.el-switch__label.is-active {
221|  color: var(--text-primary);
222|}
223|
224|/* 滚动条 */
225|::-webkit-scrollbar {
226|  width: 8px;
227|  height: 8px;
228|}
229|::-webkit-scrollbar-track {
230|  background: var(--bg-page);
231|}
232|::-webkit-scrollbar-thumb {
233|  background: var(--border-color);
234|  border-radius: 4px;
235|}
236|::-webkit-scrollbar-thumb:hover {
237|  background: var(--border-color-light);
238|}
239|

