1|import { generatePageFromInputs } from '@/utils/nocodeGenerator'
2|
3|// 通过后端代理调用大模型，避免浏览器直连 DeepSeek 时的 CORS/预检问题
4|export async function generateNoCodePage (payload) {
5|  const safePayload = payload || {}
6|  try {
7|    const res = await fetch('/api/nocode/generate', {
8|      method: 'POST',
9|      headers: { 'Content-Type': 'application/json' },
10|      body: JSON.stringify(safePayload)
11|    })
12|    const data = await res.json()
13|    if (res.ok && data && (data.html !== undefined || data.vueCode !== undefined)) {
14|      return {
15|        vueCode: data.vueCode || '',
16|        html: data.html || '',
17|        css: data.css || '',
18|        meta: data.meta || { provider: 'deepseek-chat' }
19|      }
20|    }
21|    // 接口返回非 2xx 或格式不对，记下错误信息，但仍用本地模板填充预览
22|    const errMsg = (data && data.message) ? data.message : (`HTTP ${res.status}`)
23|    console.warn('[nocode] 后端返回异常', res.status, errMsg, data && data.error)
24|    const local = generatePageFromInputs(safePayload)
25|    return {
26|      _fallback: true,
27|      _error: errMsg,
28|      _errorCode: data && data.error,
29|      vueCode: '',
30|      html: local.html,
31|      css: local.css,
32|      meta: { provider: 'local-template', ...(local.meta || {}) }
33|    }
34|  } catch (e) {
35|    console.warn('[nocode] 请求后端失败，使用本地模板', e)
36|  }
37|  const local = generatePageFromInputs(safePayload)
38|  return {
39|    _fallback: true,
40|    _error: (e && e.message) || '网络异常',
41|    vueCode: '',
42|    html: local.html,
43|    css: local.css,
44|    meta: { provider: 'local-template', ...(local.meta || {}) }
45|  }
46|}
